local ServiceDescriptor = require(script.Parent.ServiceDescriptor)
local ServiceLifetime = require(script.Parent.ServiceLifetime)

return function()
	describe("ServiceDescriptor", function()
		it("应该正确创建新的 ServiceDescriptor 实例", function()
			local descriptor =
				ServiceDescriptor.newWithType("TestService", "TestImplementation", ServiceLifetime.Singleton)
			expect(descriptor.ServiceType).to.equal("TestService")
			expect(descriptor.ImplementationType).to.equal("TestImplementation")
			expect(descriptor.Lifetime).to.equal(ServiceLifetime.Singleton)
		end)

		it("应该正确创建带有工厂的 ServiceDescriptor", function()
			local factory = function()
				return {}
			end
			local descriptor = ServiceDescriptor.newWithFactory("TestService", factory, ServiceLifetime.Transient)
			expect(descriptor.ServiceType).to.equal("TestService")
			expect(descriptor.ImplementationFactory).to.equal(factory)
			expect(descriptor.Lifetime).to.equal(ServiceLifetime.Transient)
		end)

		it("应该正确生成 ToString 输出", function()
			local descriptor =
				ServiceDescriptor.newWithType("TestService", "TestImplementation", ServiceLifetime.Scoped)
			local str = descriptor:ToString()
			-- str has "ServiceType: TestService"
			expect(string.find(str, "ServiceType: TestService")).to.be.ok()
			expect(string.find(str, "Lifetime: Scoped")).to.be.ok()
			expect(string.find(str, "ImplementationType: TestImplementation")).to.be.ok()
		end)

		it("应该正确获取实现类型", function()
			local descriptor1 =
				ServiceDescriptor.newWithType("TestService", "TestImplementation", ServiceLifetime.Singleton)
			expect(descriptor1:GetImplementationType()).to.equal("TestImplementation")

			local factory = function()
				return {}
			end
			local descriptor3 = ServiceDescriptor.newWithFactory("TestService", factory, ServiceLifetime.Transient)
			expect(descriptor3:GetImplementationType()).to.equal("object")
		end)

		it("应该正确创建 Transient ServiceDescriptor", function()
			local descriptor = ServiceDescriptor.Transient("TestService", "TestImplementation")
			expect(descriptor.Lifetime).to.equal(ServiceLifetime.Transient)
		end)

		it("应该正确创建 Scoped ServiceDescriptor", function()
			local descriptor = ServiceDescriptor.Scoped("TestService", "TestImplementation")
			expect(descriptor.Lifetime).to.equal(ServiceLifetime.Scoped)
		end)

		it("应该正确创建 Singleton ServiceDescriptor", function()
			local descriptor = ServiceDescriptor.Singleton("TestService", "TestImplementation")
			expect(descriptor.Lifetime).to.equal(ServiceLifetime.Singleton)
		end)

		it("应该正确创建 ModuleScript ServiceDescriptor", function()
			local descriptor =
				ServiceDescriptor.newWithModuleScript("TestService", script.Parent.ServiceDescriptor, "Scope")
		end)
	end)
end
